<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\CoupureElectrique;use App\Models\Signalement;use Illuminate\Http\Request;class SignalementController extends Controller{public function index(){return view('admin.signalements.index',['signalements'=>Signalement::with(['user','quartier','coupureElectrique'])->latest()->get()]);}public function show(Signalement $signalement){return view('admin.signalements.show',['signalement'=>$signalement->load(['user','quartier','coupureElectrique']),'coupures'=>CoupureElectrique::all()]);}public function update(Request $r,Signalement $signalement){$d=$r->validate(['statut'=>'required|in:en_attente,validé,rejeté,résolu','coupure_electrique_id'=>'nullable|exists:coupure_electriques,id']);$signalement->update($d);return back()->with('success','Signalement mis à jour.');}}
